17	type Step = {
18	  op: string;
19	  items: Item[];
20	};
21	
22	type Scenario = {
23	  customer: { yearsWithMHPCO: number };
24	  steps: Step[];
25	};
26	
27	type QuoteResult = {
28	  premium: number;
29	};
30	
31	type ScenarioOutput = {
32	  results: QuoteResult[];
33	};
34	
35	const premiumForItem = (item: Item): number => {
36	  const basePremium = BASE_PREMIUM_BY_ITEM_TYPE[item.type];
37	  return basePremium + basePremium * FIRST_INSURANCE_SURCHARGE_RATE;
38	};
39	
40	const premiumForItems = (items: Item[]): number =>
41	  items.reduce((total, item) => total + premiumForItem(item), 0);
42	
43	export const runScenario = (scenario: Scenario): ScenarioOutput => ({
44	  results: scenario.steps.map((step) => ({
45	    premium: premiumForItems(step.items) + PROCESSING_FEE,
46	  })),
47	});
